function get_splits_required(arr, max_sum) {
  let splits_required = 1;
  let current_sum = 0;

  for (const num of arr) {
    if (current_sum + num > max_sum) {
      splits_required++;
      current_sum = num; // Start a new subarray with the current number.
    } else {
      current_sum += num;
    }
  }
  return splits_required;
